import { Suspense } from "react";
import EmployeeRecord from "@/components/employee-record";
import LoadingEmployee from "./loading";

type ViewEmployeePageProps = {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ message?: string | string[] }>;
};

export default function ViewEmployeePage({
  params,
  searchParams,
}: ViewEmployeePageProps) {
  return (
    <Suspense fallback={<LoadingEmployee />}>
      <ViewEmployeeContent params={params} searchParams={searchParams} />
    </Suspense>
  );
}

async function ViewEmployeeContent({
  params,
  searchParams,
}: ViewEmployeePageProps) {
  const [{ id }, { message }] = await Promise.all([params, searchParams]);

  return (
    <EmployeeRecord
      key={id}
      id={id}
      message={typeof message === "string" ? message : undefined}
    />
  );
}
